function validate([nums, k, multiplier]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => v < 1 || v > 100)) return 'Each value of nums is from 1 to 100.';
  if (k < 1 || k > 10) return 'k is from 1 to 10.';
  if (multiplier < 1 || multiplier > 5) return 'multiplier is from 1 to 5.';
  return null;
}

