function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? int(1, 6) : int(90, 100);
  // A small top value makes many equal minimums, which tests the leftmost rule.
  const top = rand() < 0.4 ? int(1, 5) : 100;
  const nums = Array.from({ length: n }, () => int(1, top));
  return [nums, int(1, 10), int(1, 5)];
}
